/**
 * PRICING SYSTEM HEALTH CHECK v1.0
 * Run this in an n8n Code node to diagnose your market pricing system
 *
 * Checks:
 * 1. All required Redis keys exist
 * 2. Data freshness (TTLs, timestamps)
 * 3. Data integrity and counts
 * 4. Sample price validation
 * 5. Queue status
 */

const Redis = require('ioredis');

const report = {
    timestamp: new Date().toISOString(),
    status: 'HEALTHY',
    checks: {},
    warnings: [],
    errors: [],
    recommendations: []
};

let redis;

try {
    redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 10000 });

    await new Promise((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error('Redis connection timeout')), 10000);
        redis.on('ready', () => { clearTimeout(timeout); resolve(); });
        redis.on('error', (err) => { clearTimeout(timeout); reject(err); });
    });

    console.log('🔍 PRICING SYSTEM HEALTH CHECK');
    console.log('================================\n');

    // =====================================================================
    // CHECK 1: Required Keys Existence
    // =====================================================================
    console.log('📋 CHECK 1: Required Keys Existence');

    const requiredKeys = [
        { key: 'eve:market:prices', type: 'hash', description: 'Full market prices (JSON)' },
        { key: 'eve:killmail:prices', type: 'hash', description: 'Simple prices for killmails' },
        { key: 'eve:market:prices:historical', type: 'hash', description: 'Historical price data' },
        { key: 'eve:market:prices:build_cost', type: 'hash', description: 'Build cost data (JSON)' },
        { key: 'eve:market:prices:build_cost:simple', type: 'hash', description: 'Simple build costs' },
        { key: 'eve:market:prices:metadata', type: 'string', description: 'Price update metadata' },
        { key: 'eve:update_queue', type: 'list', description: 'Historical update queue' },
        { key: 'eve:item_classification', type: 'hash', description: 'Item classifications' },
        { key: 'sde:raw:industryActivityMaterials', type: 'string', description: 'SDE materials data' }
    ];

    const keyChecks = {};
    for (const { key, type, description } of requiredKeys) {
        const exists = await redis.exists(key);
        let count = 0;

        if (exists) {
            if (type === 'hash') count = await redis.hlen(key);
            else if (type === 'list') count = await redis.llen(key);
            else if (type === 'string') count = (await redis.strlen(key)) > 0 ? 1 : 0;
        }

        keyChecks[key] = { exists: exists === 1, count, description };

        const status = exists ? `✅ EXISTS (${count.toLocaleString()} entries)` : '❌ MISSING';
        console.log(`   ${key}: ${status}`);

        if (!exists) {
            report.errors.push(`Missing required key: ${key} - ${description}`);
            report.status = 'CRITICAL';
        }
    }
    report.checks.requiredKeys = keyChecks;

    // =====================================================================
    // CHECK 2: Data Freshness
    // =====================================================================
    console.log('\n📋 CHECK 2: Data Freshness');

    const freshnessChecks = {};

    // Market prices metadata
    const metadataRaw = await redis.get('eve:market:prices:metadata');
    if (metadataRaw) {
        try {
            const metadata = JSON.parse(metadataRaw);
            const lastUpdate = new Date(metadata.last_update);
            const hoursSince = (Date.now() - lastUpdate.getTime()) / (1000 * 60 * 60);

            freshnessChecks.marketPrices = {
                lastUpdate: metadata.last_update,
                hoursSince: hoursSince.toFixed(1),
                totalPrices: metadata.total_prices,
                manipulationOverrides: metadata.manipulation_overrides || 0,
                buildCostFallbacks: metadata.build_cost_fallbacks || 0
            };

            console.log(`   Market Prices: Updated ${hoursSince.toFixed(1)} hours ago`);
            console.log(`      - Total prices: ${metadata.total_prices?.toLocaleString()}`);
            console.log(`      - Manipulation overrides: ${metadata.manipulation_overrides || 0}`);
            console.log(`      - Build cost fallbacks: ${metadata.build_cost_fallbacks || 0}`);

            if (hoursSince > 26) {
                report.warnings.push(`Market prices are ${hoursSince.toFixed(1)} hours old (should update daily)`);
                if (report.status === 'HEALTHY') report.status = 'WARNING';
            }
        } catch (e) {
            report.errors.push('Failed to parse market prices metadata');
        }
    }

    // Build cost metadata
    const buildMetaRaw = await redis.get('eve:market:prices:build_cost:metadata');
    if (buildMetaRaw) {
        try {
            const buildMeta = JSON.parse(buildMetaRaw);
            const lastUpdate = new Date(buildMeta.last_update);
            const hoursSince = (Date.now() - lastUpdate.getTime()) / (1000 * 60 * 60);

            freshnessChecks.buildCosts = {
                lastUpdate: buildMeta.last_update,
                hoursSince: hoursSince.toFixed(1),
                itemsCalculated: buildMeta.items_calculated
            };

            console.log(`   Build Costs: Updated ${hoursSince.toFixed(1)} hours ago`);
            console.log(`      - Items calculated: ${buildMeta.items_calculated}`);
        } catch (e) {
            report.warnings.push('Failed to parse build cost metadata');
        }
    }

    // Historical prices - sample to check freshness
    const historicalSample = await redis.hget('eve:market:prices:historical', '44992'); // PLEX
    if (historicalSample) {
        try {
            const hist = JSON.parse(historicalSample);
            const lastUpdate = new Date(hist.last_updated);
            const hoursSince = (Date.now() - lastUpdate.getTime()) / (1000 * 60 * 60);

            freshnessChecks.historical = {
                sampleItem: 'PLEX (44992)',
                lastUpdate: hist.last_updated,
                hoursSince: hoursSince.toFixed(1)
            };

            console.log(`   Historical (PLEX sample): Updated ${hoursSince.toFixed(1)} hours ago`);
        } catch (e) {}
    }

    report.checks.freshness = freshnessChecks;

    // =====================================================================
    // CHECK 3: Queue Status
    // =====================================================================
    console.log('\n📋 CHECK 3: Historical Update Queue');

    const queueLength = await redis.llen('eve:update_queue');
    const historicalCount = await redis.hlen('eve:market:prices:historical');

    const queueStatus = {
        queueLength,
        historicalCount,
        coveragePercent: queueLength > 0 ? ((historicalCount / queueLength) * 100).toFixed(1) : 0
    };

    console.log(`   Queue length: ${queueLength.toLocaleString()} items`);
    console.log(`   Historical records: ${historicalCount.toLocaleString()}`);
    console.log(`   Coverage: ${queueStatus.coveragePercent}%`);

    if (queueLength === 0) {
        report.warnings.push('Update queue is empty - run "Build Queue" node');
        if (report.status === 'HEALTHY') report.status = 'WARNING';
    }

    if (historicalCount < queueLength * 0.5) {
        report.recommendations.push(`Historical coverage is ${queueStatus.coveragePercent}% - let the queue processor run to build more data`);
    }

    report.checks.queue = queueStatus;

    // =====================================================================
    // CHECK 4: Sample Price Validation
    // =====================================================================
    console.log('\n📋 CHECK 4: Sample Price Validation');

    const sampleItems = [
        { id: '34', name: 'Tritanium', expectedRange: [1, 100] },
        { id: '44992', name: 'PLEX', expectedRange: [1e9, 10e9] },
        { id: '29668', name: 'Large Skill Injector', expectedRange: [500e6, 2e9] },
        { id: '11567', name: 'Avatar (Titan)', expectedRange: [50e9, 200e9] },
        { id: '23773', name: 'Nyx (Supercarrier)', expectedRange: [15e9, 50e9] },
        { id: '28606', name: 'Orca', expectedRange: [500e6, 2e9] }
    ];

    const priceValidation = [];

    for (const item of sampleItems) {
        const [marketRaw, killmailPrice, historicalRaw, buildCost] = await Promise.all([
            redis.hget('eve:market:prices', item.id),
            redis.hget('eve:killmail:prices', item.id),
            redis.hget('eve:market:prices:historical', item.id),
            redis.hget('eve:market:prices:build_cost:simple', item.id)
        ]);

        let marketData = null;
        let historicalData = null;

        try { marketData = marketRaw ? JSON.parse(marketRaw) : null; } catch (e) {}
        try { historicalData = historicalRaw ? JSON.parse(historicalRaw) : null; } catch (e) {}

        const effectivePrice = marketData?.effective_price || parseFloat(killmailPrice) || 0;
        const buildCostVal = parseFloat(buildCost) || 0;

        const validation = {
            id: item.id,
            name: item.name,
            effectivePrice,
            killmailPrice: parseFloat(killmailPrice) || 0,
            historicalAvg: historicalData?.robust_average || null,
            buildCost: buildCostVal || null,
            priceSource: marketData?.price_source || 'unknown',
            validationStatus: marketData?.validation_status || 'unknown',
            inExpectedRange: effectivePrice >= item.expectedRange[0] && effectivePrice <= item.expectedRange[1]
        };

        priceValidation.push(validation);

        const rangeStatus = validation.inExpectedRange ? '✅' : '⚠️';
        const priceStr = effectivePrice > 1e9
            ? `${(effectivePrice / 1e9).toFixed(2)}B`
            : effectivePrice > 1e6
                ? `${(effectivePrice / 1e6).toFixed(1)}M`
                : effectivePrice.toLocaleString();

        console.log(`   ${rangeStatus} ${item.name}: ${priceStr} ISK (source: ${validation.priceSource})`);

        if (!validation.inExpectedRange && effectivePrice > 0) {
            report.warnings.push(`${item.name} price (${priceStr}) outside expected range`);
        }
    }

    report.checks.priceValidation = priceValidation;

    // =====================================================================
    // CHECK 5: Data Integrity
    // =====================================================================
    console.log('\n📋 CHECK 5: Data Integrity Spot Check');

    // Check for malformed entries
    let malformedCount = 0;
    let checkedCount = 0;
    const sampleSize = 100;

    const randomSample = await redis.hrandfield('eve:market:prices', sampleSize, 'WITHVALUES');

    if (randomSample && randomSample.length > 0) {
        for (let i = 0; i < randomSample.length; i += 2) {
            checkedCount++;
            try {
                const parsed = JSON.parse(randomSample[i + 1]);
                if (!parsed.type_id || parsed.effective_price === undefined) {
                    malformedCount++;
                }
            } catch (e) {
                malformedCount++;
            }
        }
    }

    const integrityStatus = {
        sampleSize: checkedCount,
        malformedCount,
        integrityPercent: checkedCount > 0 ? (((checkedCount - malformedCount) / checkedCount) * 100).toFixed(1) : 0
    };

    console.log(`   Checked ${checkedCount} random entries`);
    console.log(`   Malformed: ${malformedCount}`);
    console.log(`   Integrity: ${integrityStatus.integrityPercent}%`);

    if (malformedCount > 0) {
        report.warnings.push(`Found ${malformedCount} malformed price entries in sample`);
    }

    report.checks.integrity = integrityStatus;

    // =====================================================================
    // FINAL SUMMARY
    // =====================================================================
    console.log('\n================================');
    console.log(`📊 OVERALL STATUS: ${report.status}`);
    console.log('================================');

    if (report.errors.length > 0) {
        console.log('\n❌ ERRORS:');
        report.errors.forEach(e => console.log(`   - ${e}`));
    }

    if (report.warnings.length > 0) {
        console.log('\n⚠️ WARNINGS:');
        report.warnings.forEach(w => console.log(`   - ${w}`));
    }

    if (report.recommendations.length > 0) {
        console.log('\n💡 RECOMMENDATIONS:');
        report.recommendations.forEach(r => console.log(`   - ${r}`));
    }

    return [{ json: report }];

} catch (error) {
    console.error('❌ Health check failed:', error.message);
    report.status = 'ERROR';
    report.errors.push(error.message);
    return [{ json: report }];
} finally {
    if (redis) await redis.quit().catch(() => {});
}

/**
 * PRICING CHAIN VERIFICATION v1.0
 * Run this in an n8n Code node to verify the entire pricing pipeline is working
 *
 * Tests:
 * 1. ESI → Market Price Indexer → eve:market:prices (with validation)
 * 2. ESI History → Process Queue → eve:market:prices:historical
 * 3. SDE → Build Cost Calculator → eve:market:prices:build_cost
 * 4. Killmail Valuation uses correct fallback chain
 */

const Redis = require('ioredis');
const axios = require('axios');

const report = {
    timestamp: new Date().toISOString(),
    allTestsPassed: true,
    tests: {}
};

let redis;

try {
    redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 10000 });

    await new Promise((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error('Redis timeout')), 10000);
        redis.on('ready', () => { clearTimeout(timeout); resolve(); });
        redis.on('error', reject);
    });

    console.log('🔬 PRICING CHAIN VERIFICATION');
    console.log('==============================\n');

    // =====================================================================
    // TEST 1: Market Price Structure
    // =====================================================================
    console.log('🧪 TEST 1: Market Price Structure (eve:market:prices)');

    const test1 = { passed: true, details: {} };

    // Check PLEX (always has market data)
    const plexMarket = await redis.hget('eve:market:prices', '44992');
    if (plexMarket) {
        try {
            const parsed = JSON.parse(plexMarket);
            const requiredFields = ['type_id', 'effective_price', 'price_source', 'validation_status', 'last_updated'];
            const missingFields = requiredFields.filter(f => parsed[f] === undefined);

            if (missingFields.length > 0) {
                test1.passed = false;
                test1.details.missingFields = missingFields;
                console.log(`   ❌ Missing required fields: ${missingFields.join(', ')}`);
            } else {
                console.log('   ✅ PLEX entry has all required fields');
                console.log(`      - effective_price: ${parsed.effective_price?.toLocaleString()} ISK`);
                console.log(`      - price_source: ${parsed.price_source}`);
                console.log(`      - validation_status: ${parsed.validation_status}`);
            }

            test1.details.plexData = {
                effective_price: parsed.effective_price,
                price_source: parsed.price_source,
                validation_status: parsed.validation_status
            };
        } catch (e) {
            test1.passed = false;
            test1.details.error = 'Failed to parse PLEX market data';
            console.log('   ❌ Failed to parse PLEX market data');
        }
    } else {
        test1.passed = false;
        test1.details.error = 'PLEX not found in eve:market:prices';
        console.log('   ❌ PLEX not found in eve:market:prices');
    }

    // Check killmail:prices matches
    const plexKillmail = await redis.hget('eve:killmail:prices', '44992');
    const plexMarketParsed = plexMarket ? JSON.parse(plexMarket) : null;
    if (plexKillmail && plexMarketParsed) {
        const killmailPrice = parseFloat(plexKillmail);
        const marketEffective = plexMarketParsed.effective_price;

        if (Math.abs(killmailPrice - marketEffective) < 1) {
            console.log('   ✅ eve:killmail:prices matches eve:market:prices effective_price');
        } else {
            console.log(`   ⚠️ Price mismatch: killmail=${killmailPrice}, market=${marketEffective}`);
            test1.details.priceMismatch = { killmail: killmailPrice, market: marketEffective };
        }
    }

    report.tests.marketPriceStructure = test1;
    if (!test1.passed) report.allTestsPassed = false;

    // =====================================================================
    // TEST 2: Historical Price Data
    // =====================================================================
    console.log('\n🧪 TEST 2: Historical Price Data (eve:market:prices:historical)');

    const test2 = { passed: true, details: {} };

    const historicalCount = await redis.hlen('eve:market:prices:historical');
    test2.details.totalRecords = historicalCount;
    console.log(`   Total historical records: ${historicalCount.toLocaleString()}`);

    if (historicalCount < 100) {
        test2.passed = false;
        console.log('   ❌ Insufficient historical data (need at least 100 records)');
    } else {
        console.log('   ✅ Historical data exists');
    }

    // Check structure of a historical entry
    const histSample = await redis.hget('eve:market:prices:historical', '44992');
    if (histSample) {
        try {
            const parsed = JSON.parse(histSample);
            const requiredFields = ['type_id', 'robust_average', 'volatility_percent', 'manipulation_risk', 'last_updated'];
            const missingFields = requiredFields.filter(f => parsed[f] === undefined);

            if (missingFields.length > 0) {
                test2.passed = false;
                test2.details.missingFields = missingFields;
                console.log(`   ❌ Historical entry missing fields: ${missingFields.join(', ')}`);
            } else {
                console.log('   ✅ Historical entry has correct structure');
                console.log(`      - robust_average: ${parsed.robust_average?.toLocaleString()} ISK`);
                console.log(`      - volatility: ${parsed.volatility_percent?.toFixed(1)}%`);
                console.log(`      - risk: ${parsed.manipulation_risk}`);
            }

            test2.details.sampleData = {
                robust_average: parsed.robust_average,
                volatility_percent: parsed.volatility_percent,
                manipulation_risk: parsed.manipulation_risk
            };
        } catch (e) {
            test2.passed = false;
            test2.details.error = 'Failed to parse historical sample';
        }
    }

    report.tests.historicalData = test2;
    if (!test2.passed) report.allTestsPassed = false;

    // =====================================================================
    // TEST 3: Build Cost Data
    // =====================================================================
    console.log('\n🧪 TEST 3: Build Cost Data (eve:market:prices:build_cost)');

    const test3 = { passed: true, details: {} };

    const buildCostCount = await redis.hlen('eve:market:prices:build_cost');
    const buildCostSimpleCount = await redis.hlen('eve:market:prices:build_cost:simple');

    test3.details.fullRecords = buildCostCount;
    test3.details.simpleRecords = buildCostSimpleCount;

    console.log(`   Full build cost records: ${buildCostCount}`);
    console.log(`   Simple build cost records: ${buildCostSimpleCount}`);

    if (buildCostCount < 10) {
        test3.passed = false;
        console.log('   ❌ Insufficient build cost data');
    } else {
        console.log('   ✅ Build cost data exists');
    }

    // Check a capital ship build cost
    const titanBuildCost = await redis.hget('eve:market:prices:build_cost:simple', '11567'); // Avatar
    if (titanBuildCost) {
        const cost = parseFloat(titanBuildCost);
        test3.details.titanBuildCost = cost;
        console.log(`   Avatar (Titan) build cost: ${(cost / 1e9).toFixed(2)}B ISK`);

        if (cost < 50e9 || cost > 300e9) {
            console.log('   ⚠️ Titan build cost seems unusual (expected 50-300B)');
        } else {
            console.log('   ✅ Titan build cost in expected range');
        }
    } else {
        console.log('   ⚠️ Avatar build cost not found (may not be calculated yet)');
    }

    report.tests.buildCostData = test3;
    if (!test3.passed) report.allTestsPassed = false;

    // =====================================================================
    // TEST 4: Validation Pipeline (Manipulation Detection)
    // =====================================================================
    console.log('\n🧪 TEST 4: Validation Pipeline (Manipulation Detection)');

    const test4 = { passed: true, details: {} };

    // Find items where validation was applied
    let validatedCount = 0;
    let overriddenCount = 0;
    const sampleSize = 500;

    const randomSample = await redis.hrandfield('eve:market:prices', sampleSize, 'WITHVALUES');
    if (randomSample && randomSample.length > 0) {
        for (let i = 0; i < randomSample.length; i += 2) {
            try {
                const parsed = JSON.parse(randomSample[i + 1]);
                if (parsed.validation_status === 'validated') validatedCount++;
                if (parsed.validation_status === 'manipulation_detected') overriddenCount++;
            } catch (e) {}
        }
    }

    test4.details.sampleSize = sampleSize;
    test4.details.validatedCount = validatedCount;
    test4.details.overriddenCount = overriddenCount;

    console.log(`   Sampled ${sampleSize} prices:`);
    console.log(`      - Validated against history: ${validatedCount}`);
    console.log(`      - Manipulation overrides: ${overriddenCount}`);

    if (validatedCount === 0 && overriddenCount === 0) {
        console.log('   ⚠️ No items have been validated yet (historical data still building)');
        test4.details.note = 'Historical data still building - validation will improve over time';
    } else {
        console.log('   ✅ Validation pipeline is active');
    }

    report.tests.validationPipeline = test4;

    // =====================================================================
    // TEST 5: Killmail Valuation Simulation
    // =====================================================================
    console.log('\n🧪 TEST 5: Killmail Valuation Simulation');

    const test5 = { passed: true, details: {} };

    // Simulate the exact logic from Node 5
    const testItems = [
        { id: 11567, name: 'Avatar (Titan)', expectBuildCostFallback: true },
        { id: 44992, name: 'PLEX', expectBuildCostFallback: false },
        { id: 34, name: 'Tritanium', expectBuildCostFallback: false }
    ];

    for (const item of testItems) {
        const [marketRaw, buildCostRaw] = await Promise.all([
            redis.hget('eve:market:prices', item.id.toString()),
            redis.hget('eve:market:prices:build_cost:simple', item.id.toString())
        ]);

        let marketPrice = 0;
        try {
            const parsed = JSON.parse(marketRaw);
            marketPrice = parsed.effective_price || 0;
        } catch (e) {}

        const buildCost = parseFloat(buildCostRaw) || 0;

        // Simulate Node 5 fallback logic
        let finalPrice = marketPrice;
        let usedFallback = false;

        if (buildCost > 0 && (marketPrice === 0 || marketPrice < buildCost * 0.5)) {
            finalPrice = buildCost;
            usedFallback = true;
        }

        const priceStr = finalPrice > 1e9
            ? `${(finalPrice / 1e9).toFixed(2)}B`
            : finalPrice > 1e6
                ? `${(finalPrice / 1e6).toFixed(1)}M`
                : finalPrice.toLocaleString();

        console.log(`   ${item.name}:`);
        console.log(`      - Market price: ${marketPrice > 0 ? (marketPrice / 1e9).toFixed(2) + 'B' : 'N/A'}`);
        console.log(`      - Build cost: ${buildCost > 0 ? (buildCost / 1e9).toFixed(2) + 'B' : 'N/A'}`);
        console.log(`      - Final price: ${priceStr}`);
        console.log(`      - Used fallback: ${usedFallback ? '✅ Yes' : 'No'}`);

        test5.details[item.name] = {
            marketPrice,
            buildCost,
            finalPrice,
            usedFallback
        };

        if (item.expectBuildCostFallback && !usedFallback && buildCost > 0) {
            console.log(`      ⚠️ Expected build cost fallback but market price was used`);
        }
    }

    report.tests.valuationSimulation = test5;

    // =====================================================================
    // TEST 6: Live ESI Comparison
    // =====================================================================
    console.log('\n🧪 TEST 6: Live ESI Comparison (optional)');

    const test6 = { passed: true, details: {} };

    try {
        const esiResponse = await axios.get('https://esi.evetech.net/latest/markets/prices/', {
            headers: { 'User-Agent': 'EVE-Alfred-Bot/3.0' },
            timeout: 10000
        });

        const esiPrices = new Map();
        esiResponse.data.forEach(item => {
            esiPrices.set(item.type_id, item.average_price || item.adjusted_price || 0);
        });

        // Compare PLEX
        const plexEsi = esiPrices.get(44992);
        const plexRedis = parseFloat(await redis.hget('eve:killmail:prices', '44992')) || 0;

        if (plexEsi && plexRedis) {
            const diff = Math.abs(plexEsi - plexRedis) / plexEsi * 100;
            test6.details.plexComparison = {
                esi: plexEsi,
                redis: plexRedis,
                diffPercent: diff.toFixed(1)
            };

            console.log(`   PLEX price comparison:`);
            console.log(`      - ESI: ${(plexEsi / 1e9).toFixed(2)}B ISK`);
            console.log(`      - Redis: ${(plexRedis / 1e9).toFixed(2)}B ISK`);
            console.log(`      - Difference: ${diff.toFixed(1)}%`);

            if (diff > 50) {
                console.log('   ⚠️ Large price difference - may indicate manipulation override is active');
            } else {
                console.log('   ✅ Prices are within expected range');
            }
        }
    } catch (e) {
        console.log('   ⚠️ Could not fetch live ESI data for comparison');
        test6.details.error = e.message;
    }

    report.tests.esiComparison = test6;

    // =====================================================================
    // FINAL SUMMARY
    // =====================================================================
    console.log('\n==============================');
    console.log(`📊 VERIFICATION COMPLETE`);
    console.log(`   All tests passed: ${report.allTestsPassed ? '✅ YES' : '❌ NO'}`);
    console.log('==============================');

    return [{ json: report }];

} catch (error) {
    console.error('❌ Verification failed:', error.message);
    report.allTestsPassed = false;
    report.error = error.message;
    return [{ json: report }];
} finally {
    if (redis) await redis.quit().catch(() => {});
}

/**
 * MARKET PRICING ERROR CHECK v1.0
 * Run this in an n8n Code node to find and diagnose pricing errors
 *
 * Checks for:
 * 1. Zero/missing prices on valuable items
 * 2. Price mismatches between hashes
 * 3. Stale data
 * 4. Malformed entries
 * 5. Queue health
 * 6. Historical data gaps
 */

const Redis = require('ioredis');

const report = {
    timestamp: new Date().toISOString(),
    overallHealth: 'HEALTHY',
    errors: [],
    warnings: [],
    fixes: []
};

let redis;

try {
    redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 10000 });

    await new Promise((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error('Redis timeout')), 10000);
        redis.on('ready', () => { clearTimeout(timeout); resolve(); });
        redis.on('error', reject);
    });

    console.log('🔍 MARKET PRICING ERROR CHECK');
    console.log('==============================\n');

    // =====================================================================
    // ERROR CHECK 1: Zero prices on known valuable items
    // =====================================================================
    console.log('❓ ERROR CHECK 1: Zero/Missing Prices on Valuable Items');

    const criticalItems = [
        // PLEX is per-unit (~4-5M each), NOT per-500-bundle
        { id: '44992', name: 'PLEX', minExpected: 1e6 },
        { id: '29668', name: 'Large Skill Injector', minExpected: 100e6 },
        { id: '40520', name: 'Small Skill Injector', minExpected: 10e6 },
        { id: '34', name: 'Tritanium', minExpected: 1 },
        { id: '35', name: 'Pyerite', minExpected: 1 },
        // Titans
        { id: '11567', name: 'Avatar', minExpected: 50e9 },
        { id: '671', name: 'Erebus', minExpected: 50e9 },
        // Supers
        { id: '23773', name: 'Nyx', minExpected: 15e9 },
        { id: '23919', name: 'Aeon', minExpected: 15e9 },
        // Dreads
        { id: '19720', name: 'Revelation', minExpected: 1e9 },
        { id: '19726', name: 'Moros', minExpected: 1e9 },
        // Industrial
        { id: '28606', name: 'Orca', minExpected: 500e6 },
        // Structures (correct typeIDs)
        { id: '35832', name: 'Astrahus', minExpected: 500e6 },
        { id: '35833', name: 'Fortizar', minExpected: 5e9 },
        { id: '35834', name: 'Keepstar', minExpected: 100e9 }
    ];

    const missingPrices = [];

    for (const item of criticalItems) {
        const [marketRaw, killmailPrice, buildCost] = await Promise.all([
            redis.hget('eve:market:prices', item.id),
            redis.hget('eve:killmail:prices', item.id),
            redis.hget('eve:market:prices:build_cost:simple', item.id)
        ]);

        let effectivePrice = 0;
        try {
            const parsed = JSON.parse(marketRaw);
            effectivePrice = parsed?.effective_price || 0;
        } catch (e) {
            effectivePrice = parseFloat(killmailPrice) || 0;
        }

        const buildCostVal = parseFloat(buildCost) || 0;
        const finalPrice = effectivePrice > 0 ? effectivePrice : buildCostVal;

        if (finalPrice < item.minExpected) {
            missingPrices.push({
                id: item.id,
                name: item.name,
                currentPrice: finalPrice,
                expectedMin: item.minExpected,
                hasBuildCost: buildCostVal > 0
            });

            console.log(`   ❌ ${item.name}: ${finalPrice.toLocaleString()} ISK (expected >${(item.minExpected / 1e9).toFixed(1)}B)`);
            report.errors.push(`${item.name} has incorrect/missing price: ${finalPrice}`);
        } else {
            console.log(`   ✅ ${item.name}: ${(finalPrice / 1e9).toFixed(2)}B ISK`);
        }
    }

    if (missingPrices.length > 0) {
        report.overallHealth = 'WARNING';
        report.fixes.push('Run Market Price Indexer to refresh prices');
        // Only suggest build cost calculator if items are missing build costs
        const needsBuildCost = missingPrices.some(p => !p.hasBuildCost);
        if (needsBuildCost) {
            report.fixes.push('Run Build Cost Calculator for capitals/structures');
        }
    }

    // =====================================================================
    // ERROR CHECK 2: Price hash mismatch
    // =====================================================================
    console.log('\n❓ ERROR CHECK 2: Price Hash Consistency');

    let mismatchCount = 0;
    const sampleSize = 100;

    const sampleIds = await redis.hrandfield('eve:market:prices', sampleSize);

    if (sampleIds && sampleIds.length > 0) {
        const [marketPrices, killmailPrices] = await Promise.all([
            redis.hmget('eve:market:prices', ...sampleIds),
            redis.hmget('eve:killmail:prices', ...sampleIds)
        ]);

        for (let i = 0; i < sampleIds.length; i++) {
            try {
                const market = JSON.parse(marketPrices[i]);
                const killmail = parseFloat(killmailPrices[i]) || 0;
                const marketEffective = market?.effective_price || 0;

                if (Math.abs(marketEffective - killmail) > 1 && marketEffective > 0) {
                    mismatchCount++;
                }
            } catch (e) {}
        }

        console.log(`   Checked ${sampleSize} items, found ${mismatchCount} mismatches`);

        if (mismatchCount > sampleSize * 0.1) {
            report.warnings.push(`${mismatchCount} price mismatches between eve:market:prices and eve:killmail:prices`);
            report.fixes.push('Re-run Market Price Indexer to sync both hashes');
        } else {
            console.log('   ✅ Price hashes are consistent');
        }
    }

    // =====================================================================
    // ERROR CHECK 3: Stale data detection
    // =====================================================================
    console.log('\n❓ ERROR CHECK 3: Data Freshness');

    const metadataRaw = await redis.get('eve:market:prices:metadata');
    if (metadataRaw) {
        try {
            const metadata = JSON.parse(metadataRaw);
            const lastUpdate = new Date(metadata.last_update);
            const hoursSince = (Date.now() - lastUpdate.getTime()) / (1000 * 60 * 60);

            console.log(`   Market prices last updated: ${hoursSince.toFixed(1)} hours ago`);

            if (hoursSince > 48) {
                report.errors.push(`Market prices are ${hoursSince.toFixed(0)} hours old`);
                report.overallHealth = 'CRITICAL';
                console.log('   ❌ CRITICAL: Prices are very stale');
            } else if (hoursSince > 26) {
                report.warnings.push(`Market prices are ${hoursSince.toFixed(0)} hours old`);
                console.log('   ⚠️ Prices are getting stale');
            } else {
                console.log('   ✅ Prices are fresh');
            }
        } catch (e) {
            report.errors.push('Could not parse price metadata');
        }
    } else {
        report.errors.push('No price metadata found');
        report.overallHealth = 'CRITICAL';
    }

    // Check TTLs
    const marketTTL = await redis.ttl('eve:market:prices');
    const killmailTTL = await redis.ttl('eve:killmail:prices');

    console.log(`   eve:market:prices TTL: ${marketTTL > 0 ? (marketTTL / 3600).toFixed(1) + ' hours' : 'NO EXPIRY'}`);
    console.log(`   eve:killmail:prices TTL: ${killmailTTL > 0 ? (killmailTTL / 3600).toFixed(1) + ' hours' : 'NO EXPIRY'}`);

    if (marketTTL > 0 && marketTTL < 3600) {
        report.warnings.push('Market prices will expire soon');
    }

    // =====================================================================
    // ERROR CHECK 4: Queue health
    // =====================================================================
    console.log('\n❓ ERROR CHECK 4: Update Queue Health');

    const queueLength = await redis.llen('eve:update_queue');
    const historicalCount = await redis.hlen('eve:market:prices:historical');

    console.log(`   Queue length: ${queueLength.toLocaleString()}`);
    console.log(`   Historical records: ${historicalCount.toLocaleString()}`);

    if (queueLength === 0) {
        report.warnings.push('Update queue is empty');
        report.fixes.push('Run "Build Queue" node to populate the queue');
        console.log('   ⚠️ Queue is empty - historical updates won\'t run');
    } else {
        const coverage = (historicalCount / queueLength * 100).toFixed(1);
        console.log(`   Coverage: ${coverage}%`);

        if (parseFloat(coverage) < 50) {
            console.log('   ⚠️ Historical coverage is low - let queue processor run');
        } else {
            console.log('   ✅ Queue is healthy');
        }
    }

    // Check if queue items are being processed
    const firstInQueue = await redis.lindex('eve:update_queue', 0);
    if (firstInQueue) {
        const histData = await redis.hget('eve:market:prices:historical', firstInQueue);
        if (histData) {
            try {
                const parsed = JSON.parse(histData);
                const lastUpdate = new Date(parsed.last_updated);
                const hoursSince = (Date.now() - lastUpdate.getTime()) / (1000 * 60 * 60);
                console.log(`   First queue item last updated: ${hoursSince.toFixed(1)} hours ago`);
            } catch (e) {}
        }
    }

    // =====================================================================
    // ERROR CHECK 5: Malformed entries
    // =====================================================================
    console.log('\n❓ ERROR CHECK 5: Data Integrity');

    let malformedMarket = 0;
    let malformedHistorical = 0;
    const checkSize = 200;

    // Check market prices
    const marketSample = await redis.hrandfield('eve:market:prices', checkSize, 'WITHVALUES');
    if (marketSample) {
        for (let i = 0; i < marketSample.length; i += 2) {
            try {
                const parsed = JSON.parse(marketSample[i + 1]);
                if (!parsed.type_id || parsed.effective_price === undefined) {
                    malformedMarket++;
                }
            } catch (e) {
                malformedMarket++;
            }
        }
    }

    // Check historical
    const histSample = await redis.hrandfield('eve:market:prices:historical', checkSize, 'WITHVALUES');
    if (histSample) {
        for (let i = 0; i < histSample.length; i += 2) {
            try {
                const parsed = JSON.parse(histSample[i + 1]);
                if (!parsed.type_id || parsed.robust_average === undefined) {
                    malformedHistorical++;
                }
            } catch (e) {
                malformedHistorical++;
            }
        }
    }

    console.log(`   Malformed market entries: ${malformedMarket}/${checkSize}`);
    console.log(`   Malformed historical entries: ${malformedHistorical}/${checkSize}`);

    if (malformedMarket > 0 || malformedHistorical > 0) {
        report.warnings.push(`Found ${malformedMarket + malformedHistorical} malformed entries`);
    } else {
        console.log('   ✅ No malformed entries detected');
    }

    // =====================================================================
    // ERROR CHECK 6: Build cost coverage
    // =====================================================================
    console.log('\n❓ ERROR CHECK 6: Build Cost Coverage');

    const buildCostCount = await redis.hlen('eve:market:prices:build_cost:simple');
    console.log(`   Build cost records: ${buildCostCount}`);

    // Check specific capitals
    const capitalChecks = [
        { id: '11567', name: 'Avatar' },
        { id: '671', name: 'Erebus' },
        { id: '23773', name: 'Nyx' },
        { id: '23919', name: 'Aeon' },
        { id: '19720', name: 'Revelation' },
        { id: '19726', name: 'Moros' }
    ];
    const capitalIds = capitalChecks.map(c => c.id);
    const capitalCosts = await redis.hmget('eve:market:prices:build_cost:simple', ...capitalIds);

    const missingCapitalsList = [];
    for (let i = 0; i < capitalIds.length; i++) {
        const cost = parseFloat(capitalCosts[i]) || 0;
        if (cost === 0) {
            missingCapitalsList.push(capitalChecks[i].name);
            console.log(`      ❌ ${capitalChecks[i].name} (${capitalChecks[i].id}): NO BUILD COST`);
        } else {
            console.log(`      ✅ ${capitalChecks[i].name}: ${(cost / 1e9).toFixed(2)}B`);
        }
    }

    if (missingCapitalsList.length > 0) {
        console.log(`   ⚠️ Missing: ${missingCapitalsList.join(', ')}`);
        report.warnings.push(`Capital ships missing build costs: ${missingCapitalsList.join(', ')}`);
        report.fixes.push('Run Build Cost Calculator');
    } else {
        console.log('   ✅ All checked capitals have build costs');
    }

    // =====================================================================
    // SUMMARY
    // =====================================================================
    console.log('\n==============================');
    console.log(`📊 OVERALL HEALTH: ${report.overallHealth}`);
    console.log('==============================');

    if (report.errors.length > 0) {
        console.log('\n❌ ERRORS:');
        report.errors.forEach(e => console.log(`   - ${e}`));
    }

    if (report.warnings.length > 0) {
        console.log('\n⚠️ WARNINGS:');
        report.warnings.forEach(w => console.log(`   - ${w}`));
    }

    if (report.fixes.length > 0) {
        console.log('\n🔧 RECOMMENDED FIXES:');
        [...new Set(report.fixes)].forEach(f => console.log(`   - ${f}`));
    }

    if (report.errors.length === 0 && report.warnings.length === 0) {
        console.log('\n✅ No errors or warnings detected!');
    }

    return [{ json: report }];

} catch (error) {
    console.error('❌ Error check failed:', error.message);
    report.overallHealth = 'ERROR';
    report.errors.push(error.message);
    return [{ json: report }];
} finally {
    if (redis) await redis.quit().catch(() => {});
}

