    // 3. Check blueprint -> product mapping
    console.log('\n📋 3. Blueprint -> Product Mapping:');
    const productsCSV = await redis.get('sde:raw:industryActivityProducts');
    if (productsCSV) {
        const lines = productsCSV.split('\n');
        const headers = lines[0].split(',').map(h => h.trim());
        console.log(`   CSV Headers: ${headers.join(', ')}`);

        // Find ALL blueprints that produce Avatar (11567)
        const avatarBlueprints = lines.filter(line => {
            const parts = line.split(',');
            return parts[2]?.trim() === avatarId && parts[1] === '1';
        });

        console.log(`   Blueprints producing Avatar (${avatarId}): ${avatarBlueprints.length}`);
        avatarBlueprints.forEach(line => console.log(`      ${line.trim()}`));

        // Find ALL blueprints that produce Erebus (671)
        const erebusBlueprints = lines.filter(line => {
            const parts = line.split(',');
            return parts[2]?.trim() === '671' && parts[1] === '1';
        });

        console.log(`   Blueprints producing Erebus (671): ${erebusBlueprints.length}`);
        erebusBlueprints.forEach(line => console.log(`      ${line.trim()}`));
    }

