    const materialsCSV = await redis.get('sde:raw:industryActivityMaterials');
    const pricesRaw = await redis.hgetall('eve:killmail:prices');

    if (materialsCSV) {
        const lines = materialsCSV.split('\n');
        const avatarMats = lines.filter(line => line.startsWith(avatarBpId + ',1,'));

        console.log(`   Avatar BP ${avatarBpId} has ${avatarMats.length} materials`);

