        for (const matLine of avatarMats) {
            const parts = matLine.split(',');
            const matTypeId = parts[2];
            const quantity = parseInt(parts[3]) || 0;
            const price = parseFloat(pricesRaw[matTypeId] || 0);
            const lineCost = price * quantity;
            totalCost += lineCost;

            if (price <= 0) {
                missingPrices++;
                console.log(`   ❌ ${matTypeId}: qty=${quantity}, price=0 (MISSING!)`);
            } else {
                console.log(`   ✅ ${matTypeId}: qty=${quantity}, price=${(price/1e6).toFixed(1)}M, total=${(lineCost/1e9).toFixed(2)}B`);
