        }
    }

    // 5. Simulate Build Cost Calculator logic for Avatar
    console.log('\n🔬 5. Simulating Build Cost Calculator Logic:');

    // Parse the same way as Build Cost Calculator
    function parseCSV(csv) {
        const lines = csv.trim().split('\n');
        const headers = lines[0].split(',').map(h => h.trim());
        return lines.slice(1).map(line => {
            const values = line.split(',');
            const obj = {};
            headers.forEach((h, i) => {
                obj[h] = values[i]?.trim();
            });
            return obj;
        });
    }

    const products = parseCSV(productsCSV)
        .filter(row => row.activityID === '1')
        .map(row => ({
            blueprintTypeID: parseInt(row.typeID),
            productTypeID: parseInt(row.productTypeID),
            quantity: parseInt(row.quantity) || 1
        }));

    const materials = parseCSV(materialsCSV)
        .filter(row => row.activityID === '1')
        .map(row => ({
            blueprintTypeID: parseInt(row.typeID),
            materialTypeID: parseInt(row.materialTypeID),
            quantity: parseInt(row.quantity)
        }));

    // Build maps
    const bpToProduct = new Map();
    products.forEach(p => {
        bpToProduct.set(p.blueprintTypeID, p.productTypeID);
    });

    const bpMaterials = new Map();
    materials.forEach(m => {
        if (!bpMaterials.has(m.blueprintTypeID)) {
            bpMaterials.set(m.blueprintTypeID, []);
        }
        bpMaterials.get(m.blueprintTypeID).push(m);
    });

