    if (!str) return '';
    if (str.toLowerCase() === 'hp') return 'hp';
    if (str.toLowerCase() === 'cpu output') return 'cpuOutput';

    let s = str.replace(/[^a-zA-Z0-9 ]/g, '').replace(/^(.)/, ($1) => $1.toLowerCase())
        .replace(/ (.)/g, ($1) => $1.toUpperCase())
        .replace(/ /g, '');

    if (s === 'capacitorCapacity') return 'capacitorCapacity';
    if (s === 'rechargeRate') return 'capacitorRechargeTime'; 
    if (s === 'cargoCapacity') return 'cargoCapacity';

    return s.charAt(0).toLowerCase() + s.slice(1);
}

