    console.log('🔧 Loading build costs for fallback...');
    const buildCostRaw = await redis.hgetall('eve:market:prices:build_cost:simple');
    const buildCosts = new Map();
    for (const [typeId, cost] of Object.entries(buildCostRaw)) {
        buildCosts.set(parseInt(typeId), parseFloat(cost));
    }
    console.log(`   Loaded ${buildCosts.size} build cost records`);

    // Fetch market prices from ESI
    console.log('📡 Fetching market prices from ESI...');
    const response = await axios.get('https://esi.evetech.net/latest/markets/prices/', {
        headers: {
            'User-Agent': 'EVE-Alfred-Bot/3.0 - Market Price Indexer'
        }
    });

    const priceData = response.data;
    console.log(`✅ Received ${priceData.length} price entries from ESI`);

    if (!Array.isArray(priceData) || priceData.length === 0) {
        throw new Error('Invalid or empty price data received from ESI');
    }

    // Prepare Redis pipeline for bulk storage
    const pipeline = redis.pipeline();
    let pricesStored = 0;
    let pricesWithAdjusted = 0;
    let pricesWithAverage = 0;
    let pricesValidated = 0;
    let manipulationOverrides = 0;
    let buildCostFallbacks = 0;

    const priceIndex = {};
    const manipulatedItems = [];

    for (const item of priceData) {
        if (!item.type_id) continue;

        // Base price: Prioritize average_price, fall back to adjusted_price
        let rawPrice = item.average_price || item.adjusted_price || 0;
        let effectivePrice = rawPrice;
        let priceSource = 'esi';
        let validationStatus = 'unvalidated';

        // VALIDATION: Check against historical data
        const historical = historicalPrices.get(item.type_id);
        if (historical && historical.robust_average > 0) {
            pricesValidated++;
            const ratio = rawPrice / historical.robust_average;

            if (ratio > MANIPULATION_THRESHOLD || ratio < (1 / MANIPULATION_THRESHOLD)) {
                // Potential manipulation detected!
                manipulationOverrides++;
                effectivePrice = historical.robust_average;
                priceSource = 'historical_override';
                validationStatus = 'manipulation_detected';

                manipulatedItems.push({
                    type_id: item.type_id,
                    raw_price: rawPrice,
                    historical_avg: historical.robust_average,
                    ratio: ratio.toFixed(2)
                });
            } else {
                validationStatus = 'validated';
            }
        }

        // FALLBACK: Use build cost if no valid price
        if (effectivePrice <= 0 && buildCosts.has(item.type_id)) {
            effectivePrice = buildCosts.get(item.type_id);
            priceSource = 'build_cost';
            buildCostFallbacks++;
        }

        const priceEntry = {
            type_id: item.type_id,
            adjusted_price: item.adjusted_price || null,
            average_price: item.average_price || null,
            effective_price: effectivePrice,
            raw_esi_price: rawPrice,
            price_source: priceSource,
            validation_status: validationStatus,
            last_updated: new Date().toISOString()
        };

        // 1. Store full JSON entry for general market lookups
        pipeline.hset('eve:market:prices', item.type_id.toString(), JSON.stringify(priceEntry));

        // 2. Store simple price-only entry for fast killmail processing
        pipeline.hset('eve:killmail:prices', item.type_id.toString(), effectivePrice);

        priceIndex[item.type_id] = effectivePrice;
        pricesStored++;

        if (item.adjusted_price) pricesWithAdjusted++;
        if (item.average_price) pricesWithAverage++;
    }

    // Apply manual price overrides for AT ships and ultra-rare items
    let manualOverrideCount = 0;
    for (const [typeId, override] of MANUAL_PRICE_OVERRIDES) {
        const priceEntry = {
            type_id: typeId,
            adjusted_price: null,
            average_price: null,
            effective_price: override.price,
            raw_esi_price: 0,
            price_source: 'manual_override',
            validation_status: 'manual_override',
            last_updated: new Date().toISOString()
        };
        pipeline.hset('eve:market:prices', typeId.toString(), JSON.stringify(priceEntry));
        pipeline.hset('eve:killmail:prices', typeId.toString(), override.price);
        priceIndex[typeId] = override.price;
        manualOverrideCount++;
    }
    console.log(`\n🏆 Manual price overrides applied: ${manualOverrideCount}`);

    // Store metadata about this price update
    const metadata = {
        last_update: new Date().toISOString(),
        total_prices: pricesStored,
        prices_with_adjusted: pricesWithAdjusted,
        prices_with_average: pricesWithAverage,
        prices_validated: pricesValidated,
        manipulation_overrides: manipulationOverrides,
        build_cost_fallbacks: buildCostFallbacks,
        manual_overrides: manualOverrideCount,
        manipulation_threshold: MANIPULATION_THRESHOLD,
        source: 'ESI /markets/prices/ + validation',
        next_update_recommended: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
    };

    pipeline.set('eve:market:prices:metadata', JSON.stringify(metadata));

    // Execute all Redis operations
    console.log('💾 Storing prices in Redis (both full and killmail-simple hashes)...');
    await pipeline.exec();

    // Set TTL to 25 hours (refresh daily, but give 1 hour buffer)
    await redis.expire('eve:market:prices', 25 * 60 * 60);
    await redis.expire('eve:killmail:prices', 25 * 60 * 60);

    console.log('✅ Market price index updated successfully');
    console.log(`📊 Stats:`);
    console.log(`    - Total prices stored: ${pricesStored.toLocaleString()}`);
    console.log(`    - With adjusted price: ${pricesWithAdjusted.toLocaleString()}`);
    console.log(`    - With average price: ${pricesWithAverage.toLocaleString()}`);
    console.log(`    - Validated against history: ${pricesValidated.toLocaleString()}`);
    console.log(`    - Manipulation overrides: ${manipulationOverrides}`);
    console.log(`    - Build cost fallbacks: ${buildCostFallbacks}`);
    console.log(`    - Cache TTL: 25 hours`);

    // Log manipulated items if any
    if (manipulatedItems.length > 0) {
        console.log('\n⚠️ MANIPULATION DETECTED - Price overrides applied:');
        manipulatedItems.slice(0, 10).forEach(item => {
