// Helper function for chunked download
async function downloadChunked(url, fileName, minSize) {
    console.log(`  🔄 Switching to chunked download for ${fileName}...`);

    const chunks = [];
    let currentByte = 0;
    let totalBytes = 0;
    const maxChunks = Math.ceil((minSize * 2) / CHUNK_SIZE);

    for (let chunkNum = 0; chunkNum < maxChunks; chunkNum++) {
        try {
            const startByte = currentByte;
            const endByte = startByte + CHUNK_SIZE - 1;

            const response = await axios.get(url, {
                headers: { 
                    'User-Agent': 'EVE-Alfred-Bot/3.0',
                    'Accept-Encoding': 'identity',
                    'Range': `bytes=${startByte}-${endByte}`,
                    'Connection': 'close'
                },
                responseType: 'arraybuffer',
                timeout: 60000,
                maxRedirects: 5
            });

            const chunk = Buffer.from(response.data);
            const chunkSize = chunk.length;

            // If server returns full file (status 200), use it
            if (response.status === 200 && chunkSize >= minSize) {
                console.log(`  ✅ Server sent full file (${chunkSize.toLocaleString()} bytes)`);
                return chunk.toString('utf8');
            }

            // Handle partial content (206)
            if (response.status === 206) {
                chunks.push(chunk);
                totalBytes += chunkSize;
                currentByte += chunkSize;

                // End of file reached
                if (chunkSize < CHUNK_SIZE) {
                    console.log(`  ✅ Chunked download complete: ${totalBytes.toLocaleString()} bytes`);
                    return Buffer.concat(chunks).toString('utf8');
                }
            }

            // Check if we have enough
            if (totalBytes >= minSize) {
                console.log(`  ✅ Minimum size reached: ${totalBytes.toLocaleString()} bytes`);
                return Buffer.concat(chunks).toString('utf8');
            }

        } catch (error) {
            console.error(`  ❌ Chunk ${chunkNum} failed: ${error.message}`);
            // Continue trying more chunks
        }
    }

    // If we got here, check if we have enough data
    if (chunks.length > 0) {
        const combined = Buffer.concat(chunks);
        const totalSize = combined.length;
        if (totalSize >= minSize) {
            console.log(`  ⚠️ Partial success: ${totalSize.toLocaleString()} bytes`);
            return combined.toString('utf8');
        }
    }

    throw new Error(`Chunked download failed - only got ${totalBytes} bytes, needed ${minSize}`);
}

