            // Check for success
            if (response.status === 200 && responseSize > 10) {
                // If file has min_size requirement, check it
                if (min_size > 1 && responseSize < min_size) {
                    // File too small - try chunked download
                    console.warn(`  ⚠️ File too small (${responseSize} < ${min_size}), trying chunked...`);

                    try {
