            } else if (!isNaN(val) && val !== '') {
                obj[header] = Number(val);
            } else {
                obj[header] = val;
            }
        });
        results.push(obj);
    }
    return results;
}

async function scanAll(pattern) {
    const keys = [];
    let cursor = '0';
    do {
        const [newCursor, scannedKeys] = await redis.scan(cursor, 'MATCH', pattern, 'COUNT', 5000);
        cursor = newCursor;
        keys.push(...scannedKeys);
    } while (cursor !== '0');
    return keys;
}

