            if (pi.isInput === 1) acc[pi.schematicID].inputs.push(item);
            else acc[pi.schematicID].outputs.push(item);
        }
        return acc;
    }, {});

    // C. Build final index keyed by *Product TypeID*
    const piProductMap = {};
    for (const [schematicID, io] of Object.entries(piIO)) {
        if (io.outputs.length > 0) {
