                piProductMap[product.typeID] = {
                    productTypeID: product.typeID,
                    productName: schematic.name, // Schematic name = product name
                    productQuantity: product.quantity,
                    cycleTime: schematic.cycleTime,
                    inputs: io.inputs
                };
            }
        }
    }

    pipeline = redis.pipeline();
    let schematicCount = 0;
    for (const [id, data] of Object.entries(piSchematicInfo)) {
        pipeline.hset('eve:pi_schematics', id, JSON.stringify(data));
