    report.items_indexed += (schematicCount + piTypeCount + piTypeMapCount);
    // --- END NEW PI LOGIC ---

    // --- 7. NEW: Item Traits Index ---
    console.log('Building "Item Traits Index" (eve:item_traits_by_type)...');
    pipeline = redis.pipeline();
    const traits = Array.isArray(allData.invTraits) ? allData.invTraits : Object.values(allData.invTraits || {});
    let traitCount = 0;
    const traitsByType = {};

    if (traits.length > 0) {
        for (const trait of traits) {
            if (trait.typeID && trait.skillID) {
                // Original index
                pipeline.hset('eve:item_traits', `${trait.typeID}:${trait.skillID}`, JSON.stringify(trait));
                traitCount++;

                // NEW index
                if (!traitsByType[trait.typeID]) traitsByType[trait.typeID] = [];
                traitsByType[trait.typeID].push(trait);
            }
        }
    }

    console.log(`✅ Indexed ${traitCount} item traits (legacy key).`);

    let traitByTypeCount = 0;
    for (const [typeID, traitList] of Object.entries(traitsByType)) {
        pipeline.hset('eve:item_traits_by_type', typeID, JSON.stringify(traitList));
        traitByTypeCount++;
    }

    if (pipeline.length > 0) await pipeline.exec();
    report.indexes_created.push('eve:item_traits', 'eve:item_traits_by_type');
    report.items_indexed += (traitCount + traitByTypeCount);
    console.log(`✅ Indexed ${traitByTypeCount} items in new traits-by-type index.`);
    // --- END NEW TRAITS LOGIC ---

    report.status = 'success';
    console.log('--- ✅ Branch 4: Finished Successfully ---');

} catch (error) {
    report.status = 'failed';
    report.error = error.message;
    console.error('--- ❌ Branch 4: FAILED ---', error.message);
    console.error(error.stack);
} finally {
    if (redis && redis.status === 'ready') {
        await redis.quit();
    } else if (redis) {
        redis.disconnect();
    }
}

return [{ json: report }];

