const Redis = require('ioredis');

/**
 * BUILD COST CALCULATOR v1.0
 * Calculates material-based pricing for capitals, structures, and other
 * items where market data is unreliable or missing.
 * 
 * Uses industryActivityMaterials SDE data + current material prices
 * Stores in 'eve:market:prices:build_cost' as fallback pricing
 */

// Group IDs for items that need build cost calculation
const BUILD_COST_GROUPS = new Set([
    // Capitals
    30,    // Titan (legacy groupID)
    775,   // Titan (current groupID - Avatar, Erebus, etc.)
    659,   // Supercarrier
    485,   // Dreadnought
    4594,  // Lancer Dreadnought
    547,   // Carrier
    1538,  // Force Auxiliary
    883,   // Capital Industrial Ship (Rorqual)
    902,   // Jump Freighter
    513,   // Freighter

    // Structures
    1404,  // Engineering Complex
    1406,  // Citadel
    1657,  // Refinery
    1408,  // Upwell Jump Gate (Ansiblex)
    2016,  // Observatory (Pharolux)
    2017,  // Navigation Structure

    // Misc large items
    941,   // Industrial Command Ship (Orca, Porpoise)
]);

let redis;

try {
    console.log('🔧 Starting Build Cost Calculator...');

    redis = new Redis({
        host: 'redis',
        port: 6379,
        db: 0,
        connectTimeout: 10000
    });

    await new Promise((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error('Redis connection timeout')), 10000);
        redis.on('ready', () => { clearTimeout(timeout); resolve(); });
        redis.on('error', (err) => { clearTimeout(timeout); reject(err); });
    });

    // Load required SDE data
    console.log('📡 Loading SDE data from Redis...');
    const [materialsCSV, productsCSV, itemClassRaw, pricesRaw] = await Promise.all([
        redis.get('sde:raw:industryActivityMaterials'),
        redis.get('sde:raw:industryActivityProducts'),
        redis.hgetall('eve:item_classification'),
        redis.hgetall('eve:killmail:prices')
    ]);

    if (!materialsCSV || !productsCSV) {
        throw new Error('Missing SDE data - run daily indexer first');
    }

    // Parse CSV helper
    function parseCSV(csv) {
        const lines = csv.trim().split('\n');
        const headers = lines[0].split(',').map(h => h.trim());
        return lines.slice(1).map(line => {
            const values = line.split(',');
            const obj = {};
            headers.forEach((h, i) => {
                obj[h] = values[i]?.trim();
            });
            return obj;
        });
    }

    // Parse materials (activity 1 = manufacturing)
    console.log('🔍 Parsing blueprint materials...');
    const materials = parseCSV(materialsCSV)
        .filter(row => row.activityID === '1')
        .map(row => ({
            blueprintTypeID: parseInt(row.typeID),
            materialTypeID: parseInt(row.materialTypeID),
            quantity: parseInt(row.quantity)
        }));

    // Parse products to map blueprint -> product
    const products = parseCSV(productsCSV)
        .filter(row => row.activityID === '1')
        .map(row => ({
            blueprintTypeID: parseInt(row.typeID),
            productTypeID: parseInt(row.productTypeID),
            quantity: parseInt(row.quantity) || 1
        }));

    // Build blueprint -> product mapping
    const bpToProduct = new Map();
    products.forEach(p => {
        bpToProduct.set(p.blueprintTypeID, p.productTypeID);
    });

    // Build blueprint -> materials mapping
    const bpMaterials = new Map();
    materials.forEach(m => {
        if (!bpMaterials.has(m.blueprintTypeID)) {
            bpMaterials.set(m.blueprintTypeID, []);
        }
        bpMaterials.get(m.blueprintTypeID).push({
            materialTypeID: m.materialTypeID,
            quantity: m.quantity
        });
    });

    // Filter to only items in our target groups
    console.log('🎯 Filtering to capital/structure items...');
    const targetProducts = new Set();

    for (const [typeIdStr, classJson] of Object.entries(itemClassRaw)) {
        try {
            const classification = JSON.parse(classJson);
            if (BUILD_COST_GROUPS.has(classification.groupID)) {
                targetProducts.add(parseInt(typeIdStr));
            }
        } catch (e) {}
    }

    console.log(`✅ Found ${targetProducts.size} items needing build cost calculation`);

    // Find blueprints that produce our target items
    const targetBlueprints = new Map();
    for (const [bpId, productId] of bpToProduct.entries()) {
        if (targetProducts.has(productId)) {
            targetBlueprints.set(bpId, productId);
        }
    }

    console.log(`📋 Found ${targetBlueprints.size} blueprints to process`);

    // Calculate build costs
    const pipeline = redis.pipeline();
    let successCount = 0;
    let failCount = 0;
    const buildCostResults = [];

    for (const [bpId, productId] of targetBlueprints.entries()) {
        const mats = bpMaterials.get(bpId);
        if (!mats || mats.length === 0) {
            failCount++;
            continue;
        }

        let totalCost = 0;
        let missingMaterials = 0;
        const materialBreakdown = [];

        for (const mat of mats) {
            const matPrice = parseFloat(pricesRaw[mat.materialTypeID] || 0);
            if (matPrice <= 0) {
                missingMaterials++;
            }
            const lineCost = matPrice * mat.quantity;
            totalCost += lineCost;
            materialBreakdown.push({
                typeID: mat.materialTypeID,
                quantity: mat.quantity,
                unitPrice: matPrice,
                lineCost: lineCost
            });
        }

        if (totalCost > 0) {
            const buildEntry = {
                product_type_id: productId,
                blueprint_type_id: bpId,
                build_cost: totalCost,
                material_count: mats.length,
                missing_prices: missingMaterials,
                confidence: missingMaterials === 0 ? 'high' : (missingMaterials < mats.length * 0.2 ? 'medium' : 'low'),
                last_updated: new Date().toISOString()
            };

            pipeline.hset('eve:market:prices:build_cost', productId.toString(), JSON.stringify(buildEntry));

            // Also store just the price for quick lookup
            pipeline.hset('eve:market:prices:build_cost:simple', productId.toString(), totalCost.toString());

            buildCostResults.push({
                productId,
                buildCost: totalCost,
                confidence: buildEntry.confidence
            });

            successCount++;
        } else {
            failCount++;
        }
    }

    // Store metadata
    const metadata = {
        last_update: new Date().toISOString(),
        items_calculated: successCount,
        items_failed: failCount,
        target_groups: Array.from(BUILD_COST_GROUPS)
    };
    pipeline.set('eve:market:prices:build_cost:metadata', JSON.stringify(metadata));

    // Execute pipeline
    console.log('💾 Storing build costs in Redis...');
    await pipeline.exec();

    // Set TTL to 25 hours
    await redis.expire('eve:market:prices:build_cost', 25 * 60 * 60);
    await redis.expire('eve:market:prices:build_cost:simple', 25 * 60 * 60);

    // Log sample results
    console.log('✅ Build Cost Calculator Complete!');
    console.log(`📊 Stats:`);
    console.log(`    - Items calculated: ${successCount}`);
    console.log(`    - Items failed: ${failCount}`);

    if (buildCostResults.length > 0) {
        console.log('\n🔍 Sample Build Costs (Top 5 by value):');
        const topItems = buildCostResults.sort((a, b) => b.buildCost - a.buildCost).slice(0, 5);
        for (const item of topItems) {
            console.log(`    TypeID ${item.productId}: ${(item.buildCost / 1e9).toFixed(2)}B ISK (${item.confidence})`);
        }
    }

    return [{
        json: {
            status: 'success',
            timestamp: new Date().toISOString(),
            items_calculated: successCount,
            items_failed: failCount,
            sample_results: buildCostResults.slice(0, 10)
        }
    }];

} catch (error) {
    console.error('❌ Build cost calculation failed:', error.message);
    console.error(error.stack);
    return [{
        json: {
            status: 'failed',
            timestamp: new Date().toISOString(),
            error: error.message
        }
    }];
} finally {
    if (redis && redis.status === 'ready') {
        await redis.quit();
    }
}

const Redis = require('ioredis');

// CONFIG
const HIGH_VALUE_THRESHOLD = 100000000; // 100M ISK
const QUEUE_KEY = 'eve:update_queue';

// Critical items that MUST be in queue regardless of current price
// (ESI often returns wrong prices for these)
const CRITICAL_ITEMS = [
    // PLEX & Injectors
    '44992',  // PLEX
    '29668',  // Large Skill Injector
    '40520',  // Small Skill Injector
    // Titans
    '11567', '671', '23757', '3764',
    // Supercarriers
    '23773', '23919', '22852', '23913',
    // Dreadnoughts
    '19720', '19722', '19724', '19726',
    // Carriers
    '23757', '23911', '24483', '24311',
    // FAX
    '37604', '37605', '37606', '37607',
    // Structures
    '35832', '35833', '35834', '35825', '35826', '35827', '35835', '35836',
    // Rorqual, Orca
    '28606', '28352'
];

const redis = new Redis({
    host: 'redis',
    port: 6379,
    db: 0,
    connectTimeout: 5000
});

try {
    let cursor = '0';
    const targetSet = new Set(CRITICAL_ITEMS); // Start with critical items

    // 1. Scan Redis for High Value Items
    do {
        const [newCursor, rawData] = await redis.hscan('eve:killmail:prices', cursor, 'COUNT', 1000);
        cursor = newCursor;

        for (let i = 0; i < rawData.length; i += 2) {
            const price = parseFloat(rawData[i + 1]);
            if (price >= HIGH_VALUE_THRESHOLD) {
                targetSet.add(rawData[i]); // Add to Set (dedupes)
            }
        }
    } while (cursor !== '0');

    const targets = Array.from(targetSet);

    // 2. Reset the Queue
    await redis.del(QUEUE_KEY);

    // 3. Populate Queue (Chunked to prevent command too large errors)
    const chunkSize = 500;
    for (let i = 0; i < targets.length; i += chunkSize) {
        const chunk = targets.slice(i, i + chunkSize);
        await redis.rpush(QUEUE_KEY, ...chunk);
    }

    console.log(`✅ Queue rebuilt with ${targets.length} items (${CRITICAL_ITEMS.length} critical + high-value).`);
    return [{ json: { status: 'success', total_items: targets.length, critical_items: CRITICAL_ITEMS.length } }];

} finally {
    await redis.quit();
}

const Redis = require('ioredis');
const axios = require('axios');

// --- CONFIG ---
const QUEUE_KEY = 'eve:update_queue';
const HISTORICAL_HASH = 'eve:market:prices:historical';
const PRICE_HASH = 'eve:killmail:prices';
const JITA_REGION = 10000002;
const BATCH_SIZE = 10;

let redis = null;

const calculateStats = (prices) => {
    if (!prices.length) return { mean: 0, volatility: 0 };
    const mean = prices.reduce((a, b) => a + b, 0) / prices.length;
    const variance = prices.reduce((sum, p) => sum + Math.pow(p - mean, 2), 0) / prices.length;
    return { mean, volatility: mean > 0 ? (Math.sqrt(variance) / mean) * 100 : 0 };
};

const processItem = async (typeId, currentPrice) => {
    try {
        const url = `https://esi.evetech.net/latest/markets/${JITA_REGION}/history/?type_id=${typeId}`;
        const response = await axios.get(url, { 
            headers: { 'User-Agent': 'EVE-Alfred-Bot/3.0' },
            timeout: 10000,
            validateStatus: (status) => status < 500
        });

        if (response.status !== 200) return null;
        const history = response.data;
        if (!Array.isArray(history) || history.length < 5) return null;

        const recent = history.slice(-30);
        const prices = recent.map(d => d.average).filter(p => p > 0);
        const volumes = recent.map(d => d.volume).filter(v => v > 0);
        if (prices.length < 5) return null;

        const sorted = [...prices].sort((a, b) => a - b);
        const trimmed = sorted.slice(Math.floor(sorted.length * 0.1), Math.ceil(sorted.length * 0.9));
        const robustAverage = trimmed.length > 0 ? trimmed.reduce((a, b) => a + b, 0) / trimmed.length : 0;

        const { volatility } = calculateStats(prices);
        const avgVolume = volumes.length > 0 ? volumes.reduce((a, b) => a + b, 0) / volumes.length : 0;

        let risk = 'low';
        if (currentPrice > robustAverage * 3 || currentPrice < robustAverage * 0.33) risk = 'high';
        else if (currentPrice > robustAverage * 1.5 || currentPrice < robustAverage * 0.67) risk = 'medium';

        return {
            type_id: parseInt(typeId),
            robust_average: robustAverage,
            volatility_percent: volatility,
            avg_daily_volume: avgVolume,
            manipulation_risk: risk,
            last_updated: new Date().toISOString()
        };
    } catch (e) { 
        return null; 
    }
};

try {
    redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000, maxRetriesPerRequest: 1 });

    const typeIds = await redis.lpop(QUEUE_KEY, BATCH_SIZE);
    if (!typeIds || typeIds.length === 0) {
        await redis.quit().catch(() => {});
        return [{ json: { status: 'empty_queue' } }];
    }

    await redis.rpush(QUEUE_KEY, ...typeIds);
    const currentPrices = await redis.hmget(PRICE_HASH, ...typeIds);

    // Use allSettled to handle partial failures gracefully
    const promises = typeIds.map((id, index) => 
        processItem(id, parseFloat(currentPrices[index] || 0))
    );
    const settled = await Promise.allSettled(promises);
    const results = settled.map(r => r.status === 'fulfilled' ? r.value : null);

    const pipeline = redis.pipeline();
    let savedCount = 0;
    results.forEach(res => {
        if (res) {
            pipeline.hset(HISTORICAL_HASH, res.type_id.toString(), JSON.stringify(res));
            savedCount++;
        }
    });

    if (savedCount > 0) await pipeline.exec();
    await redis.quit().catch(() => {});

    return [{ json: { 
        status: 'success', 
        processed: typeIds.length, 
        saved: savedCount, 
        items: typeIds 
    }}];

} catch (err) {
    if (redis) await redis.quit().catch(() => {});
    return [{ json: { status: 'error', message: err.message } }];
}
